// Generated by Kargo: bundles a browser app with Rollup. The only argument is the JSON file of options. It runs from the
// directory that holds Rollup's node_modules.
import { readFileSync, writeFileSync } from 'node:fs';
import { isAbsolute, relative, resolve, sep } from 'node:path';
import commonjs from '@rollup/plugin-commonjs';
import { nodeResolve } from '@rollup/plugin-node-resolve';
import terser from '@rollup/plugin-terser';
import { rollup } from 'rollup';

const options = JSON.parse(readFileSync(process.argv[2], 'utf8'));
const replacements = options.replace.map((r) => ({ dir: resolve(r.dir), from: r.from, to: r.to }));

// Whether `file` is one of the compiler's modules in `dir`: below it, but not in a package.
const inside = (file, dir) => {
  const rel = relative(dir, file);
  return rel !== '' && !rel.startsWith('..') && !isAbsolute(rel) && !rel.split(sep).includes('node_modules');
};

// Rewrites the names of files the bundler cannot see, such as the `.wasm` file a Kotlin/Wasm module fetches.
const rewrite = {
  name: 'kargo-rewrite',
  transform(code, id) {
    const mine = replacements.filter((r) => inside(resolve(id), r.dir));
    if (mine.length === 0) return null;
    const text = code;
    for (const r of mine) code = code.split(r.from).join(r.to);
    return code === text ? null : { code, map: null };
  },
};

const plugins = [rewrite, nodeResolve({ browser: true, preferBuiltins: false }), commonjs()];
if (options.minify) plugins.push(terser({ module: true }));

try {
  const bundle = await rollup({
    input: options.input,
    external: (id) => options.external.some((name) => id === name || id.startsWith(`${name}/`)),
    plugins,
    // Rollup treats a package it cannot find as external; a browser could not load it, so this is an error.
    onwarn: (warning) => {
      if (warning.code === 'UNRESOLVED_IMPORT') throw new Error(warning.message);
      console.error(warning.message);
    },
  });
  const { output } = await bundle.write({
    dir: options.outDir,
    format: 'es',
    sourcemap: options.sourceMaps,
    entryFileNames: '[name]-[hash].js',
    chunkFileNames: 'chunk-[hash].js',
    assetFileNames: '[name]-[hash][extname]',
  });
  await bundle.close();
  const entry = output.find((chunk) => chunk.type === 'chunk' && chunk.isEntry);
  writeFileSync(options.manifest, JSON.stringify({ entry: entry.fileName }));
} catch (error) {
  console.error(error.message ?? String(error));
  process.exit(1);
}
